struct string_buf {
    void *data;
    int ref_count;
    int char_length;
};

class stringx {
    char *chars;
    string_buf *my_buf;

public:
    stringx(const stringx &);
    stringx(const char *, int = -1);
    ~stringx();
    int length() const { return my_buf->char_length; }
    void to_lower();
};

class TextString {
public:
    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
    virtual void setHJustify(int);
    virtual void setVJustify(int);
    virtual void setFont(void *);
    virtual void setButtonScale(float);
    virtual void numberSpacing(bool);
    virtual void changeText(stringx);
};

class BoxText : public TextString {
public:
    void makeBox(int, int, bool, float = -1.0f, int = -1);
};

enum SaveErrors {
    SE_NO_MEMORY_CARDS
};

class DialogMenu {
    char padding[0x160];
    BoxText *message;
    BoxText *prompt;
    int type;
    char remaining[4];
    SaveErrors current_error;

public:
    void SetTypeAndMessage(SaveErrors, int ty, stringx str);
};

void DialogMenu::SetTypeAndMessage(SaveErrors, int ty, stringx str)
{
	type = ty;
	if (str.length() > 40)
	{
		message->changeText(str);
		prompt->changeText("");
		message->makeBox(240, 75, false);
		prompt->makeBox(240, 75, false);
	}
	else
	{
		str.to_lower();
		prompt->changeText(str);
		message->changeText("");
		message->makeBox(240, 75, false);
		prompt->makeBox(240, 75, false);
	}
}
